// Use "take" to view a sample number of records in the table and check the data.
YOUR_TABLE_HERE
| take 100

// See how many records are in the table.
YOUR_TABLE_HERE
| count

// This query returns the number of ingestions per hour in the given table.
YOUR_TABLE_HERE
| summarize IngestionCount = count() by bin(ingestion_time(), 1h)

// ============================================================
// Energy-Charts → Fabric Eventhouse (Datenbank: eh_1)
// Jeden Block einzeln im KQL-Queryset ausführen.
// ============================================================

// ------------------------------------------------------------
// 1) Rohdaten-Tabelle (append-only, ein Datensatz pro Wert)
// ------------------------------------------------------------
.create-merge table energy_raw (
    endpoint: string,       // public_power | signal | cbpf
    country: string,        // z. B. "de"
    ts: datetime,           // Beginn des Intervalls (UTC)
    series_id: string,      // z. B. "wind_onshore", "solar", "fr"
    series_name: string,    // Anzeigename laut API
    value: real,
    unit: string,           // MW, GW, % ...
    is_forecast: bool,      // true = Intervall lag beim Abruf in der Zukunft
    generated_at: datetime  // Erzeugungszeitpunkt der API-Antwort (UTC)
)

// ------------------------------------------------------------
// 2) JSON-Mapping für den Eventstream
// ------------------------------------------------------------
.create-or-alter table energy_raw ingestion json mapping 'energy_raw_json'
'[{"column":"endpoint","Properties":{"Path":"$.endpoint"}},{"column":"country","Properties":{"Path":"$.country"}},{"column":"ts","Properties":{"Path":"$.ts"}},{"column":"series_id","Properties":{"Path":"$.series_id"}},{"column":"series_name","Properties":{"Path":"$.series_name"}},{"column":"value","Properties":{"Path":"$.value"}},{"column":"unit","Properties":{"Path":"$.unit"}},{"column":"is_forecast","Properties":{"Path":"$.is_forecast"}},{"column":"generated_at","Properties":{"Path":"$.generated_at"}}]'

// 3) Rohdaten dauerhaft aufbewahren (100 Jahre), 30 Tage im Hot Cache
.alter-merge table energy_raw policy retention softdelete = 36500d recoverability = enabled

.alter table energy_raw policy caching hot = 30d



// 4) Deduplizierte Sicht: jeweils der zuletzt gelieferte Wert
//    je Endpoint/Land/Serie/Zeitstempel (spätere Korrekturen gewinnen)
.create materialized-view with (backfill=true) energy_latest on table energy_raw
{
    energy_raw
    | summarize arg_max(generated_at, value, unit, series_name, is_forecast)
        by endpoint, country, series_id, ts
}


// 5) Materialized View ebenfalls dauerhaft, 1 Jahr im Hot Cache
.alter-merge materialized-view energy_latest policy retention softdelete = 36500d recoverability = enabled

.alter materialized-view energy_latest policy caching hot = 365d


// 6) Kontrolle
.show table energy_raw policy retention

.show materialized-view energy_latest policy retention

let cbpf_ts = energy_latest
    | where endpoint == "cbpf" and series_id != "sum"
    | summarize Gemeldet = countif(value != 0) by ts;
let cbpf_max = toscalar(energy_latest | where endpoint == "cbpf" | summarize max(ts));
let voll11 = toscalar(cbpf_ts | where ts <= cbpf_max - 30m and Gemeldet >= 11 | summarize max(ts));
let voll10 = toscalar(cbpf_ts | where ts <= cbpf_max - 30m and Gemeldet >= 10 | summarize max(ts));
let LetzterVollstaendig = iff(isnotnull(voll11) and voll11 >= cbpf_max - 6h, voll11, voll10);
energy_latest
| where endpoint == "cbpf" and ts == LetzterVollstaendig
| summarize Summe_Laender = round(sumif(value, series_id != "sum"), 2),
            API_Summe = round(maxif(value, series_id == "sum"), 2),
            Laender_gemeldet = countif(series_id != "sum" and value != 0)
| extend Stand = datetime_utc_to_local(LetzterVollstaendig, "Europe/Berlin")

// ------------------------------------------------------------
// E1) Tabelle für Sekundenwerte
// ------------------------------------------------------------
.create-merge table frequency_raw (
    ts: datetime,           // Sekunde der Messung (UTC)
    hz: real,               // Netzfrequenz in Hertz
    generated_at: datetime  // Erzeugungszeitpunkt der API-Antwort (UTC)
)


// ------------------------------------------------------------
// E2) Dauerhaft aufbewahren, 7 Tage im Hot Cache
// ------------------------------------------------------------
.alter-merge table frequency_raw policy retention softdelete = 36500d recoverability = enabled

.alter table frequency_raw policy caching hot = 7d


// ------------------------------------------------------------
// E3) Deduplizierte Sekundenwerte (nach Neustarts der Funktion
//     können Sekunden doppelt ankommen)
// ------------------------------------------------------------
.create materialized-view with (backfill=true) frequency_1s on table frequency_raw
{
    frequency_raw
    | summarize hz = take_any(hz) by ts
}

.alter-merge materialized-view frequency_1s policy retention softdelete = 36500d recoverability = enabled



// ------------------------------------------------------------
// E4) Minuten-Sicht: Min/Mittel/Max pro Minute
//     Für schnelle Auswertungen über Tage, Wochen, Monate.
// ------------------------------------------------------------
.create materialized-view with (backfill=true) frequency_1min on table frequency_raw
{
    frequency_raw
    | summarize hz_min = min(hz), hz_avg = avg(hz), hz_max = max(hz), werte = count()
        by ts = bin(ts, 1m)
}

.alter-merge materialized-view frequency_1min policy retention softdelete = 36500d recoverability = enabled

.alter materialized-view frequency_1min policy caching hot = 365d



// ------------------------------------------------------------
// E5) Komfort-Funktion – Nutzung einfach als:  Netzfrequenz()
// ------------------------------------------------------------
.create-or-alter function with (folder = "Strom", docstring = "Netzfrequenz in Sekundenauflösung (dedupliziert)")
Netzfrequenz() {
    frequency_1s
    | project ts, hz, abweichung_mhz = round((hz - 50) * 1000, 1)
}
